function urlValid(value){try{const u=new URL(/^https?:\/\//i.test(value)?value:'https://'+value);if(!['https:','http:'].includes(u.protocol)||!u.hostname.includes('.')||u.username||u.password||[...u.searchParams.keys()].some(k=>/token|password|secret|api.?key|authorization/i.test(k)))return false;return u.href;}catch{return false;}}
const dialog=$('#so-dialog'), dialogBody=$('#so-dialog-body');let lastFocus;
function modal(title,html){lastFocus=dialog.open?lastFocus:document.activeElement;$('#so-dialog-title').textContent=title;dialogBody.innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;const el=$('input:not([type=checkbox]),select,button,a',dialogBody);if(el)el.focus({preventScroll:true});}
